from review import card,save,DATE

def b(title,text,citation=None):
 d=dict(title=title,text=text)
 if citation:d['citation']=citation
 return d

i='TCS-2851';_,c=card(i);refs=c['references'];refs[0]['locator']='MFCS 2022, article 28: Definition 3.1, Proposition 3.9, Theorem 4.2 (extension of the domain), and Section 6 (regular-function conjecture).'
refs.append(dict(id='reversible2024',title='Reversible Transducers over Infinite Words',authors='Luc Dartois; Paul Gastin; Loïc Germerie Guizouarn; R. Govind; Shankaranarayanan Krishna',year=2024,url='https://doi.org/10.4230/LIPIcs.CONCUR.2024.21',pdf_url='https://arxiv.org/pdf/2406.11488',locator='CONCUR 2024, article 21, introduction: identity restricted to words with finitely many a’s refutes literal same-domain equality with Büchi deterministic functions. Full author preprint also distinguishes domain refinement from output production.'))
issue='The source’s outlook says that every continuous regular function should be deterministic regular, but its rational-function theorem explicitly permits extending the domain, and Proposition 3.9 explains why this permission is necessary. Literal equality of partial-function domains is false: the 2024 paper gives a continuous regular restricted identity whose domain is not Büchi deterministic. It remains to confirm that the outlook intends the extension version, rather than another domain restriction. The broad intended output-realization question is preserved here; the known domain counterexample must not be presented as a resolution of the extension version.'
save(i,dict(title='Deterministic realization of continuous regular stream functions',formal='Can every continuous regular partial function f:A^ω⇀B^ω be realized by a deterministic two-way finite-state transducer without lookahead, allowing the domain extension used in the source’s theorem for rational functions? In this extension reading, the target is a transducer T with Dom(f)⊆Dom(T) and T(x)=f(x) for every x∈Dom(f), with no constraint on T outside Dom(f). The source’s final conjecture omits the domain qualification; exact equality of the two domains is a different, refuted reading. Confirmation of the extension reading remains part of the formulation review.',definitions='A and B are finite nonempty alphabets, and A^ω is the set of infinite sequences over A. For a partial f, continuity is relative to its domain: for every x∈Dom(f) and every output-prefix length m≥0, there exists an input-prefix length p≥0 such that all y∈Dom(f) agreeing with x on their first p symbols have f(y) agreeing with f(x) on their first m symbols. There is no requirement that p be uniform in x. In the source, regular functions are the functions described by deterministic two-way transducers with ω-regular lookahead, equivalently by copyless streaming string transducers with Müller output conditions. A lookahead test can inspect membership of an infinite input suffix in a language recognized by a finite Büchi automaton; this may depend on infinitely far future symbols. The target deterministic machine has a finite state set Q, one initial state, a read-only input ⊢x with a left-end marker at position 0, and a partial transition table which, from the state and current symbol, chooses one next state, a left/right move and a finite output word. It starts at position 0 and cannot move left of the marker. Output is appended and never revised. The source accepts precisely an infinite run whose head position tends to infinity and whose concatenated output is infinite; the machine has no extra Büchi/Müller acceptance test or lookahead oracle. Its domain consists of inputs with such a run. No time bound, bound on output delay or bound on the constructed number of states is requested. A full regular-source presentation and its domain convention must accompany a finalized extension formulation.',question_type='yes_no',answer_criterion='For the confirmed extension formulation, prove that every continuous regular f admits such a finite deterministic transducer agreeing everywhere on Dom(f), or refute this by a continuous regular f with no such extension. A counterexample only to exact domain equality, a result only for rational functions, or an implementation by an unrestricted Turing machine does not resolve that formulation.',context_blocks=[b('Continuity is finite-prefix dependence','Although inputs and outputs are infinite, every required finite output prefix must eventually be determined by a finite input prefix within the function’s domain. The question asks whether finite-state two-way processing suffices for this behavior.','primary'),b('Rational functions already have an extension theorem','Theorem 4.2 constructs a deterministic regular extension of every continuous rational function. Regular functions form a larger class, so this theorem does not complete the outlook’s proposed generalization.','primary'),b('The domain cannot be ignored','A deterministic machine with the source’s productive-run semantics has a Büchi-deterministic domain. The 2024 paper exhibits the identity on words containing only finitely many a’s: it is continuous and regular as a partial function but does not have such a domain. It still has the total identity as a deterministic extension.','reversible2024'),b('Remaining formulation issue',issue)],why='Would relate topological dependence on finite prefixes to finite-state implementation of regular transformations of infinite streams, while distinguishing output computation from exact domain recognition.',references=refs,progress=[dict(date='2022',text='The source proves deterministic regular extension for continuous rational functions and proposes the broader regular-function generalization.',citation='primary'),dict(date='2024',text='The CONCUR paper explicitly refutes literal same-domain equality with the Büchi-deterministic class and distinguishes domain refinement from production.',citation='reversible2024')],status='uncertain',status_note='Checked the source’s extension theorem, domain proposition and outlook, and read the 2024 domain counterexample. Searches through 12 September 2026 found no resolution of the general extension formulation. The final source sentence does not itself resolve the domain interpretation.',model_self_contained=False,requires_context=True,statement_review=dict(reviewed_on=DATE,status='needs_specification',remaining_issue=issue,notes=['Recovered the domain-extension issue and distinguished the refuted literal equality claim.']),importance=dict(score=c['importance']['score'],method='editorial',reason='Connects continuity, infinite-stream computation and finite-state transducer expressiveness; exact domain recognition is a substantive boundary. Existing score retained.',assessed_on=DATE),review_note='Removed technique advice, defined the target productive-run semantics and continuity, and documented rather than silently choosing between domain equality and extension.',working_summary=dict(sentences=['The question concerns regular transformations of infinite words whose output prefixes depend continuously on input prefixes.','The proposed implementation uses a deterministic two-way finite-state transducer without lookahead.','The source already proves an extension theorem for the narrower rational class.','Literal equality of partial-function domains is false, as a 2024 paper explains with a restricted identity function.','The general extension reading remains the intended candidate, but its relation to the source’s abbreviated conjecture must be confirmed.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','reversible2024'])),notes=['Defined relative continuity and deterministic productive-run semantics.','Restored the domain-extension qualification from the proved rational case.','Checked the later counterexample to literal domain equality and recorded the unresolved intended scope.','Removed suggested construction techniques.'],checked_sources=[r['url'] for r in refs]+['https://arxiv.org/abs/2406.11488','https://doi.org/10.4230/LIPIcs.ICALP.2023.121'],state='improved_unfinished')

i='TCS-2971';_,c=card(i);refs=c['references'];refs[0]['locator']='FSTTCS 2022, article 6: Section 1 (normalization and hypergraph cuts), Theorem 3 (same-vertex lower bound), and Section 4, p. 6:14 (extra-vertex question).'
refs.append(dict(id='authordraft',title='Approximate Representation of Symmetric Submodular Functions via Hypergraph Cut Functions — author draft',authors='Calvin Beideman; Karthekeyan Chandrasekaran; Chandra Chekuri; Chao Xu',year=2022,url='https://chekuri.cs.illinois.edu/papers/symsubmod-hypergraph-representation.pdf',locator='Author-hosted line-numbered draft, conclusion, lines 555–559. It retains d(A) for A⊆V and does not define placement or minimization over the extra vertices. Checked 12 September 2026.'))
issue='The extra-vertex question writes d(A) for A⊆V, but does not define how the auxiliary vertices are assigned to sides of the cut. Reading d as the ordinary cut function on V′ fixes all auxiliary vertices outside A; this is incompatible with the intended improvement for normalized symmetric functions and the source’s same-vertex lower bound. A terminal-cut interpretation such as minimizing over auxiliary placements is a different function and is not stated in either checked version. The intended evaluation rule must be supplied before the stronger representation question is a well-defined benchmark.'
save(i,dict(title='Constant-factor hypergraph representation with extra vertices',formal='For every normalized nonnegative symmetric submodular function f:2^V→ℝ≥0 on n≥1 elements, can f be represented within a universal constant factor by a weighted undirected hypergraph on V′⊇V with at most C·2^n vertices, where C is another universal constant? The source asks for values d(A) satisfying d(A)≤f(A)≤αd(A) for every A⊆V with α≥1 constant independent of n and f. Its notation does not specify how the vertices of V′∖V participate in evaluating d(A), so that evaluation rule remains unresolved.',definitions='Normalization means f(∅)=0. Symmetry means f(A)=f(V∖A) for all A⊆V, hence f(V)=0. Submodularity means f(A)+f(B)≥f(A∩B)+f(A∪B) for all A,B⊆V. A finite weighted undirected hypergraph H=(V′,E,w) has hyperedges e⊆V′ and nonnegative real weights w_e. Its ordinary cut value at S⊆V′ is cut_H(S)=Σ_{e∈E: e∩S≠∅ and e∩(V′∖S)≠∅} w_e. The vertices of V are the original elements and those of V′∖V are auxiliary. The intended approximation must hold simultaneously for all 2^n subsets using one H for each f. The bounds α and C are chosen before n and f; the vertex budget is C·2^n, not a freely chosen 2^{O(n)} exponent. No algorithm, oracle-query bound, bound on the number of hyperedges, or finite precision for weights is requested. The unresolved definition is the value assigned to A⊆V when extra vertices are available. Ordinary evaluation cut_H(A) and the terminal minimum min{cut_H(S):S⊆V′, S∩V=A} are different conventions; the source has not selected the latter.',question_type='yes_no',answer_criterion='Once the auxiliary-vertex evaluation rule is recovered, prove or refute the existence of universal constants α,C and one admissible hypergraph for every f satisfying the simultaneous multiplicative inequalities and the C·2^n vertex bound. Results using only V, additive error, a factor depending on n, or a different rule for auxiliary placement do not settle the intended question.',context_blocks=[b('Approximation must hold for every set','This is a representation theorem for the complete set function. Matching its minimum or approximating values on sampled sets does not supply the required simultaneous guarantee.','primary'),b('Extra vertices are meant to overcome a known obstruction','The source constructs symmetric submodular functions requiring factor Ω(n^{1/3}/log² n) when the hypergraph uses the same vertex set. Its final question asks whether increasing the vertex set can restore a constant factor.','primary'),b('The printed evaluation rule loses the intended extra power','With ordinary evaluation at A⊆V, normalization forces cut_H(V)=0. Nonnegative weights then prevent any positive-weight hyperedge from crossing between V and the auxiliary vertices. The auxiliary vertices consequently cannot change cut values on subsets of V. This is an editorial consistency check on the notation, not a theorem about a terminal-minimization model.','primary'),b('Both checked versions retain the ambiguity','The author-hosted draft reproduces the same notation and exponential vertex budget. It does not add a rule for optimizing auxiliary placements.','authordraft'),b('Remaining formulation issue',issue)],why='Would determine whether a larger hypergraph can represent general symmetric submodular objectives with constant distortion, a structural bridge between abstract set functions and cut optimization.',references=refs,progress=[dict(date='2022',text='The paper rules out constant-factor approximation on the original vertex set and asks whether O(2^n) vertices can overcome the obstruction.',citation='primary'),dict(date=DATE,text='The checked author-hosted draft retains the question’s missing auxiliary-placement convention.',citation='authordraft')],status='uncertain',status_note='Read the original definitions, same-vertex lower bound and complete conclusion; checked the author draft and subsequent representation literature through 12 September 2026. The displayed ordinary-cut reading collapses to the already obstructed same-vertex model, while the intended alternative evaluation rule is not specified.',model_self_contained=False,requires_context=True,statement_review=dict(reviewed_on=DATE,status='needs_specification',remaining_issue=issue,notes=['Recovered the exact constant-factor and C·2^n-vertex targets; identified missing auxiliary placement.']),importance=dict(score=c['importance']['score'],method='editorial',reason='A general representation boundary between symmetric submodular functions and hypergraph cuts, with additional vertices as the intended resource. Existing score retained.',assessed_on=DATE),review_note='Restored the omitted approximation inequalities and precise vertex budget, retained normalization, and exposed the auxiliary-placement issue instead of silently replacing d(A) by a minimum terminal cut.',working_summary=dict(sentences=['The source asks whether every symmetric submodular function has a constant-factor hypergraph representation.','It permits exponentially many vertices beyond the original ground set.','The same-vertex model already has a growing-factor lower bound.','The printed notation does not explain how the auxiliary vertices are placed when a subset is evaluated.','That rule is essential because ordinary cut evaluation would give the auxiliary vertices no useful effect for normalized functions.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','authordraft'])),notes=['Recovered normalization, universal distortion and the C·2^n vertex budget.','Defined weighted hypergraph cuts and distinguished ordinary from terminal-minimum evaluation.','Read both source versions and recorded their auxiliary-placement ambiguity.'],checked_sources=[r['url'] for r in refs]+['https://chekuri.web.engr.illinois.edu/pub.html'],state='improved_unfinished')
